MOD = 1_000_000_007
T = [1,2,4,6,9,13,19,28,41,60]

def solve_mod(M, b, mod):
    n = len(M)
    A = [list(M[i]) + [b[i] % mod] for i in range(n)]
    for col in range(n):
        pivot = None
        for row in range(col, n):
            if A[row][col] % mod != 0:
                pivot = row
                break
        if pivot is None:
            raise ValueError('No pivot')
        A[col], A[pivot] = A[pivot], A[col]
        inv = pow(A[col][col], mod-2, mod)
        for j in range(col, n+1):
            A[col][j] = (A[col][j] * inv) % mod
        for row in range(n):
            if row != col and A[row][col] != 0:
                factor = A[row][col]
                for j in range(col, n+1):
                    A[row][j] = (A[row][j] - factor * A[col][j]) % mod
    return [A[i][n] % mod for i in range(n)]

